"""Parsers for catalog.txt, movements.txt and orders.txt."""

import datetime
import re
from decimal import Decimal
from typing import Dict, Iterator, List, Optional, Sequence, Tuple

from .models import Movement, Order, Product

SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
REORDER_RE = re.compile(r"[0-9]+")
DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
SIGNED_QTY_RE = re.compile(r"[+-]?[0-9]+")
UNSIGNED_QTY_RE = re.compile(r"[0-9]+")
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
FIELD_SEP_RE = re.compile(r"[ \t]+")

TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}


class ParseError(ValueError):
    """A mistake in a data file. ``.line`` is the 1-based line number."""

    def __init__(self, line: int, message: str):
        self.line = line
        self.reason = message
        super().__init__("line %d: %s" % (line, message))


def iter_data_lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield ``(line_number, line)`` for every non-blank, non-comment line.

    Lines end at LF or CRLF only; a lone CR stays inside the line.
    """
    if text.startswith("﻿"):
        text = text[1:]
    for number, line in enumerate(text.split("\n"), start=1):
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "" or line.lstrip().startswith("#"):
            continue
        yield number, line


def parse_date(value: str) -> Optional[datetime.date]:
    """Return the date for a ``YYYY-MM-DD`` string, or None if it is not a real date."""
    if not DATE_RE.fullmatch(value):
        return None
    try:
        return datetime.date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        return None


def valid_sku(value: str) -> bool:
    return SKU_RE.fullmatch(value) is not None


def valid_order_id(value: str) -> bool:
    return ORDER_ID_RE.fullmatch(value) is not None


def order_number(order_id: str) -> int:
    return int(order_id.split("-", 1)[1])


def _split_fields(line: str, maxsplit: int = 0) -> List[str]:
    stripped = line.strip(" \t")
    return FIELD_SEP_RE.split(stripped, maxsplit=maxsplit)


def parse_catalog(text: str) -> Dict[str, Product]:
    """Parse catalog.txt text into a dict of upper-case SKU -> Product."""
    catalog: Dict[str, Product] = {}
    for number, line in iter_data_lines(text):
        fields = [field.strip() for field in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        sku, name, price, reorder = fields[:4]
        if not valid_sku(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if name == "":
            raise ParseError(number, "empty name")
        if not PRICE_RE.fullmatch(price) or Decimal(price) < Decimal("0.01"):
            raise ParseError(number, "bad price %r" % price)
        if not REORDER_RE.fullmatch(reorder):
            raise ParseError(number, "bad reorder level %r" % reorder)
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(number, "bad tax %r" % fields[4])
        catalog[sku] = Product(
            sku=sku,
            name=name,
            price=Decimal(price).quantize(Decimal("0.01")),
            reorder=int(reorder),
            tax=tax,
        )
    return catalog


def counting_order(movements: Sequence[Movement]) -> List[int]:
    """Indices of ``movements`` in the order they count: by date, same day in file order."""
    return sorted(range(len(movements)), key=lambda i: movements[i].date)


def first_negative(movements: Sequence[Movement]) -> Optional[int]:
    """Index of the first movement (in counting order) that takes a stock below zero."""
    balances: Dict[str, int] = {}
    for index in counting_order(movements):
        movement = movements[index]
        balance = balances.get(movement.sku, 0) + movement.quantity
        if balance < 0:
            return index
        balances[movement.sku] = balance
    return None


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    """Parse movements.txt text into a list of Movements in text order."""
    movements: List[Movement] = []
    numbers: List[int] = []
    for number, line in iter_data_lines(text):
        fields = _split_fields(line, maxsplit=3)
        if len(fields) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku, quantity = fields[:3]
        note = fields[3].strip() if len(fields) == 4 else ""
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date %r" % date_text)
        if not valid_sku(sku) or sku.upper() not in catalog:
            raise ParseError(number, "unknown SKU %r" % sku)
        if not SIGNED_QTY_RE.fullmatch(quantity) or int(quantity) == 0:
            raise ParseError(number, "bad quantity %r" % quantity)
        movements.append(Movement(date=date, sku=sku.upper(), quantity=int(quantity), note=note))
        numbers.append(number)
    bad = first_negative(movements)
    if bad is not None:
        movement = movements[bad]
        raise ParseError(
            numbers[bad],
            "stock of %s would go below zero on %s" % (movement.sku, movement.date.isoformat()),
        )
    return movements


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    """Parse orders.txt text into a list of Orders in text order."""
    orders: List[Order] = []
    seen = set()
    for number, line in iter_data_lines(text):
        fields = _split_fields(line)
        if len(fields) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        order_id, date_text, customer, lines_text = fields
        if not valid_order_id(order_id):
            raise ParseError(number, "bad order number %r" % order_id)
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date %r" % date_text)
        lines: List[Tuple[str, int]] = []
        skus = set()
        for item in lines_text.split(","):
            sku, star, quantity = item.partition("*")
            if not star:
                raise ParseError(number, "bad order line %r" % item)
            if not valid_sku(sku) or sku.upper() not in catalog:
                raise ParseError(number, "unknown SKU %r" % sku)
            sku = sku.upper()
            if sku in skus:
                raise ParseError(number, "SKU %s appears twice in order %s" % (sku, order_id))
            if not UNSIGNED_QTY_RE.fullmatch(quantity) or int(quantity) < 1:
                raise ParseError(number, "bad quantity %r" % quantity)
            skus.add(sku)
            lines.append((sku, int(quantity)))
        seen.add(order_id)
        orders.append(Order(id=order_id, date=date, customer=customer, lines=lines))
    return orders

