"""Exact order pricing, done in integer pennies."""

from decimal import Decimal
from typing import Dict, List

from .models import Order, Product, Quote, QuoteLine
from .parsing import TAX_RATES

ORDER_DISCOUNT_THRESHOLD = 50000  # pennies
ORDER_DISCOUNT_PERCENT = 3


def _pennies(amount: Decimal) -> int:
    return int((amount * 100).to_integral_value())


def _decimal(pennies: int) -> Decimal:
    """Exact two-decimal Decimal for an integer number of pennies (never -0.00)."""
    sign = "-" if pennies < 0 else ""
    pennies = abs(pennies)
    return Decimal("%s%d.%02d" % (sign, pennies // 100, pennies % 100))


def _percent_half_up(pennies: int, percent: int) -> int:
    """``pennies * percent / 100`` rounded to the penny, halves up (non-negative input)."""
    return (pennies * percent + 50) // 100


def volume_discount_percent(quantity: int) -> int:
    if quantity >= 50:
        return 10
    if quantity >= 10:
        return 5
    return 0


def allocate(total: int, weights: List[int]) -> List[int]:
    """Share ``total`` pennies over ``weights`` by largest remainder, earlier line first on ties."""
    whole = sum(weights)
    if total == 0 or whole == 0:
        return [0] * len(weights)
    shares = [total * w // whole for w in weights]
    remainders = [total * w % whole for w in weights]
    left = total - sum(shares)
    for index in sorted(range(len(weights)), key=lambda i: (-remainders[i], i))[:left]:
        shares[index] += 1
    return shares


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    """Price a whole order (see the Prices rules in the brief)."""
    units = []
    grosses = []
    discounts = []
    nets = []
    for sku, quantity in order.lines:
        unit = _pennies(catalog[sku].price)
        gross = unit * quantity
        discount = _percent_half_up(gross, volume_discount_percent(quantity))
        units.append(unit)
        grosses.append(gross)
        discounts.append(discount)
        nets.append(gross - discount)
    subtotal = sum(nets)
    order_discount = 0
    if subtotal >= ORDER_DISCOUNT_THRESHOLD:
        order_discount = _percent_half_up(subtotal, ORDER_DISCOUNT_PERCENT)
    shares = allocate(order_discount, nets)
    tax = 0
    for (sku, _quantity), net, share in zip(order.lines, nets, shares):
        tax += _percent_half_up(net - share, TAX_RATES[catalog[sku].tax])
    lines = [
        QuoteLine(
            sku=sku,
            quantity=quantity,
            unit=_decimal(unit),
            gross=_decimal(gross),
            discount=_decimal(-discount),
            net=_decimal(net),
        )
        for (sku, quantity), unit, gross, discount, net in zip(order.lines, units, grosses, discounts, nets)
    ]
    return Quote(
        lines=lines,
        subtotal=_decimal(subtotal),
        order_discount=_decimal(-order_discount),
        tax=_decimal(tax),
        total=_decimal(subtotal - order_discount + tax),
    )
