"""Order fulfilment state: what has shipped, what is owed, what can ship."""

import datetime
from typing import Dict, List, Optional, Sequence, Tuple

from .models import Movement, Order
from .parsing import counting_order


def order_note(order_id: str) -> str:
    return "order %s" % order_id.upper()


def shipped_so_far(order: Order, movements: Sequence[Movement]) -> List[Tuple[str, int, int]]:
    """``(sku, ordered, shipped)`` per order line; shipped is capped at ordered."""
    note = order_note(order.id)
    sent: Dict[str, int] = {}
    for movement in movements:
        if movement.quantity < 0 and movement.note == note:
            sent[movement.sku] = sent.get(movement.sku, 0) - movement.quantity
    return [(sku, quantity, min(quantity, sent.get(sku, 0))) for sku, quantity in order.lines]


def order_status(rows: Sequence[Tuple[str, int, int]]) -> str:
    if all(shipped >= ordered for _sku, ordered, shipped in rows):
        return "complete"
    if all(shipped == 0 for _sku, _ordered, shipped in rows):
        return "open"
    return "partial"


def available_on(movements: Sequence[Movement], sku: str, date: datetime.date) -> int:
    """Most of ``sku`` that can leave on ``date`` without any later balance going negative."""
    balance = 0
    lowest: Optional[int] = None
    for index in counting_order(movements):
        movement = movements[index]
        if movement.sku != sku:
            continue
        balance += movement.quantity
        if movement.date > date:
            lowest = balance if lowest is None else min(lowest, balance)
    if lowest is None:
        # No later movements: the balance now is the balance on DATE.
        limit = balance
    else:
        limit = min(_balance_on(movements, sku, date), lowest)
    return max(0, limit)


def _balance_on(movements: Sequence[Movement], sku: str, date: datetime.date) -> int:
    return sum(m.quantity for m in movements if m.sku == sku and m.date <= date)


def plan_fulfilment(
    order: Order, movements: Sequence[Movement], date: datetime.date
) -> Tuple[List[Movement], List[Tuple[str, int, int]], str]:
    """Work out a fulfilment on ``date``.

    Returns the new movements to append, ``(sku, shipped_now, backordered)`` per order line,
    and the order status afterwards.
    """
    before = shipped_so_far(order, movements)
    new: List[Movement] = []
    summary = []
    after = []
    for sku, ordered, shipped in before:
        owed = ordered - shipped
        ship = min(owed, available_on(movements, sku, date)) if owed > 0 else 0
        if ship > 0:
            new.append(Movement(date=date, sku=sku, quantity=-ship, note=order_note(order.id)))
        summary.append((sku, ship, owed - ship))
        after.append((sku, ordered, shipped + ship))
    return new, summary, order_status(after)
