"""The ``stockroom`` command."""

import csv
import io
import json
import os
import re
import sys
from typing import Dict, List, Optional, Sequence

from .models import Movement, Order, Product, Quote
from .orders import order_status, plan_fulfilment, shipped_so_far
from .parsing import (
    ParseError,
    first_negative,
    order_number,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
    valid_order_id,
    valid_sku,
)
from .pricing import price_order
from .stock import buy_quantity, history, stock_levels, stock_status

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (allowed positional counts, allowed options, files read)
COMMANDS = {
    "stock": ((0,), ("--json",), (CATALOG, MOVEMENTS)),
    "low": ((0,), ("--json",), (CATALOG, MOVEMENTS)),
    "history": ((1,), ("--json",), (CATALOG, MOVEMENTS)),
    "receive": ((3, 4), (), (CATALOG, MOVEMENTS)),
    "ship": ((3, 4), (), (CATALOG, MOVEMENTS)),
    "quote": ((1,), ("--json",), (CATALOG, ORDERS)),
    "fulfil": ((2,), (), (CATALOG, MOVEMENTS, ORDERS)),
    "invoice": ((1,), ("--json",), (CATALOG, MOVEMENTS, ORDERS)),
    "report": ((0,), ("--format",), (CATALOG, MOVEMENTS, ORDERS)),
}
RAW_COMMANDS = ("receive", "ship", "fulfil")
FORMATS = ("text", "csv", "json")
QTY_RE = re.compile(r"[0-9]+")

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND ...\n"
    "commands: stock [--json], low [--json], history SKU [--json],\n"
    "          receive DATE SKU QUANTITY [NOTE], ship DATE SKU QUANTITY [NOTE],\n"
    "          quote ORDER [--json], fulfil ORDER DATE, invoice ORDER [--json],\n"
    "          report [--format text|csv|json]"
)


class Failure(Exception):
    """Stop with an exit status and a message for stderr."""

    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status = status
        self.message = message


def usage_error(message: str) -> Failure:
    return Failure(2, "%s\n%s" % (message, USAGE))


class Request:
    def __init__(self) -> None:
        self.directory = "."
        self.command = ""
        self.positionals: List[str] = []
        self.json = False
        self.format = "text"


def parse_args(argv: Sequence[str]) -> Request:
    request = Request()
    rest: List[str] = []
    tokens = list(argv)
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token == "--dir":
            if i + 1 >= len(tokens):
                raise usage_error("option --dir needs a value")
            request.directory = tokens[i + 1]
            i += 2
            continue
        if token.startswith("--dir="):
            request.directory = token[len("--dir="):]
            i += 1
            continue
        rest.append(token)
        i += 1
    if request.directory == "":
        raise usage_error("option --dir needs a value")

    command_index = None
    for index, token in enumerate(rest):
        if not _is_option(token):
            command_index = index
            break
    if command_index is None:
        if rest:
            raise usage_error("unknown option %s" % rest[0] if rest[0] not in ("--json", "--format") or True else "")
        raise usage_error("no command given")
    command = rest[command_index]
    if command not in COMMANDS:
        raise usage_error("unknown command %r" % command)
    request.command = command
    counts, options, _files = COMMANDS[command]
    others = rest[:command_index] + rest[command_index + 1:]

    if command in RAW_COMMANDS:
        request.positionals = others
    else:
        j = 0
        while j < len(others):
            token = others[j]
            if not _is_option(token):
                request.positionals.append(token)
            elif token == "--json" and "--json" in options:
                request.json = True
            elif token == "--format" and "--format" in options:
                if j + 1 >= len(others):
                    raise usage_error("option --format needs a value")
                request.format = _check_format(others[j + 1])
                j += 1
            elif token.startswith("--format=") and "--format" in options:
                request.format = _check_format(token[len("--format="):])
            else:
                raise usage_error("unknown option %s" % token)
            j += 1

    if len(request.positionals) not in counts:
        raise usage_error("wrong number of arguments for %s" % command)
    if command in ("receive", "ship", "fulfil"):
        date_text = request.positionals[0] if command != "fulfil" else request.positionals[1]
        if parse_date(date_text) is None:
            raise usage_error("bad date %r (expected YYYY-MM-DD)" % date_text)
    return request


def _is_option(token: str) -> bool:
    return len(token) > 1 and token.startswith("-")


def _check_format(value: str) -> str:
    if value not in FORMATS:
        raise usage_error("bad value for --format: %r (expected text, csv or json)" % value)
    return value


# ---------------------------------------------------------------- files


def read_files(directory: str, names: Sequence[str]) -> Dict[str, str]:
    if not os.path.exists(directory):
        raise Failure(2, "%s: no such directory" % directory)
    if not os.path.isdir(directory):
        raise Failure(2, "%s: not a directory" % directory)
    texts = {}
    for name in names:
        path = os.path.join(directory, name)
        try:
            with open(path, "rb") as handle:
                data = handle.read()
        except FileNotFoundError:
            if name == CATALOG:
                raise Failure(2, "%s: file not found" % name)
            data = b""
        except OSError as error:
            raise Failure(2, "%s: cannot read: %s" % (name, error.strerror or error))
        try:
            texts[name] = data.decode("utf-8")
        except UnicodeDecodeError:
            raise Failure(2, "%s: not valid UTF-8" % name)
    return texts


def append_lines(directory: str, lines: Sequence[str]) -> None:
    path = os.path.join(directory, MOVEMENTS)
    payload = "".join(line + "\n" for line in lines).encode("utf-8")
    try:
        with open(path, "ab+") as handle:
            handle.seek(0, os.SEEK_END)
            if handle.tell() > 0:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    payload = b"\n" + payload
            handle.seek(0, os.SEEK_END)
            handle.write(payload)
    except OSError as error:
        raise Failure(2, "%s: cannot write: %s" % (MOVEMENTS, error.strerror or error))


class Data:
    def __init__(self, texts: Dict[str, str]):
        self.catalog: Dict[str, Product] = self._parse(CATALOG, parse_catalog, texts[CATALOG])
        self.movements: List[Movement] = []
        self.orders: List[Order] = []
        if MOVEMENTS in texts:
            self.movements = self._parse(MOVEMENTS, parse_movements, texts[MOVEMENTS], self.catalog)
        if ORDERS in texts:
            self.orders = self._parse(ORDERS, parse_orders, texts[ORDERS], self.catalog)

    @staticmethod
    def _parse(name, parser, *args):
        try:
            return parser(*args)
        except ParseError as error:
            raise Failure(1, "%s: %s" % (name, error))

    def find_order(self, order_id: str) -> Order:
        if valid_order_id(order_id):
            wanted = order_id.upper()
            for order in self.orders:
                if order.id == wanted:
                    return order
        raise Failure(1, "unknown order %r" % order_id)

    def find_sku(self, sku: str) -> str:
        if valid_sku(sku) and sku.upper() in self.catalog:
            return sku.upper()
        raise Failure(1, "unknown SKU %r" % sku)


# ---------------------------------------------------------------- output helpers


def money(amount) -> str:
    text = "%.2f" % amount if not hasattr(amount, "quantize") else str(amount)
    return "0.00" if text in ("-0.00", "0") else text


def to_json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def to_lines(lines: Sequence[str]) -> str:
    return "".join(line + "\n" for line in lines)


def movement_line(movement: Movement) -> str:
    text = "%s %s %+d" % (movement.date.isoformat(), movement.sku, movement.quantity)
    return text + (" " + movement.note if movement.note else "")


def quote_lines(header: str, order: Order, quote: Quote) -> List[str]:
    lines = ["%s%s %s %s" % (header, order.id, order.date.isoformat(), order.customer)]
    for line in quote.lines:
        lines.append(
            " ".join(
                [
                    line.sku,
                    str(line.quantity),
                    money(line.unit),
                    money(line.gross),
                    money(line.discount),
                    money(line.net),
                ]
            )
        )
    lines.append("subtotal " + money(quote.subtotal))
    lines.append("order discount " + money(quote.order_discount))
    lines.append("tax " + money(quote.tax))
    lines.append("total " + money(quote.total))
    return lines


def quote_json(order: Order, quote: Quote) -> dict:
    return {
        "order": order.id,
        "date": order.date.isoformat(),
        "customer": order.customer,
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit": money(line.unit),
                "gross": money(line.gross),
                "discount": money(line.discount),
                "net": money(line.net),
            }
            for line in quote.lines
        ],
        "subtotal": money(quote.subtotal),
        "order_discount": money(quote.order_discount),
        "tax": money(quote.tax),
        "total": money(quote.total),
    }


# ---------------------------------------------------------------- commands


def cmd_stock(request: Request, data: Data) -> str:
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        onhand = levels[sku]
        rows.append((product, onhand, stock_status(onhand, product.reorder)))
    if request.json:
        return to_json(
            [{"sku": p.sku, "name": p.name, "onhand": n, "status": s} for p, n, s in rows]
        )
    return to_lines(["%s %d %s %s" % (p.sku, n, s, p.name) for p, n, s in rows])


def cmd_low(request: Request, data: Data) -> str:
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        onhand = levels[sku]
        if stock_status(onhand, product.reorder) in ("low", "out"):
            rows.append((sku, onhand, product.reorder, buy_quantity(onhand, product.reorder)))
    if request.json:
        return to_json([{"sku": s, "onhand": n, "reorder": r, "buy": b} for s, n, r, b in rows])
    return to_lines(["%s %d %d %d" % row for row in rows])


def cmd_history(request: Request, data: Data) -> str:
    sku = data.find_sku(request.positionals[0])
    rows = history(data.movements, sku)
    if request.json:
        return to_json(
            [
                {
                    "date": m.date.isoformat(),
                    "delta": "%+d" % m.quantity,
                    "balance": balance,
                    "note": m.note,
                }
                for m, balance in rows
            ]
        )
    lines = []
    for m, balance in rows:
        text = "%s %+d %d" % (m.date.isoformat(), m.quantity, balance)
        lines.append(text + (" " + m.note if m.note else ""))
    return to_lines(lines)


def cmd_move(request: Request, data: Data) -> str:
    date_text, sku_text, quantity_text = request.positionals[:3]
    note = request.positionals[3] if len(request.positionals) == 4 else ""
    sku = data.find_sku(sku_text)
    if not QTY_RE.fullmatch(quantity_text) or int(quantity_text) == 0:
        raise Failure(1, "bad quantity %r (expected a whole number of 1 or more)" % quantity_text)
    if "\n" in note or "\r" in note:
        raise Failure(1, "a note may not contain a line break")
    quantity = int(quantity_text)
    if request.command == "ship":
        quantity = -quantity
    movement = Movement(date=parse_date(date_text), sku=sku, quantity=quantity, note=note.strip())
    check_movements(data.movements, [movement])
    line = movement_line(movement)
    append_lines(request.directory, [line])
    return line + "\n"


def check_movements(existing: Sequence[Movement], new: Sequence[Movement]) -> None:
    combined = list(existing) + list(new)
    bad = first_negative(combined)
    if bad is not None:
        movement = combined[bad]
        raise Failure(
            1,
            "refused: stock of %s would go below zero on %s"
            % (movement.sku, movement.date.isoformat()),
        )


def cmd_quote(request: Request, data: Data) -> str:
    order = data.find_order(request.positionals[0])
    quote = price_order(order, data.catalog)
    if request.json:
        return to_json(quote_json(order, quote))
    return to_lines(quote_lines("", order, quote))


def cmd_fulfil(request: Request, data: Data) -> str:
    order = data.find_order(request.positionals[0])
    date = parse_date(request.positionals[1])
    if date < order.date:
        raise Failure(
            1,
            "refused: %s is before the date of order %s (%s)"
            % (date.isoformat(), order.id, order.date.isoformat()),
        )
    new, summary, status = plan_fulfilment(order, data.movements, date)
    lines = ["%s shipped %d backordered %d" % row for row in summary]
    lines.append("status " + status)
    if new:
        check_movements(data.movements, new)
        append_lines(request.directory, [movement_line(m) for m in new])
    return to_lines(lines)


def shipped_order(order: Order, movements: Sequence[Movement]) -> Optional[Order]:
    lines = [(sku, shipped) for sku, _ordered, shipped in shipped_so_far(order, movements) if shipped > 0]
    if not lines:
        return None
    return Order(id=order.id, date=order.date, customer=order.customer, lines=lines)


def cmd_invoice(request: Request, data: Data) -> str:
    order = data.find_order(request.positionals[0])
    shipped = shipped_order(order, data.movements)
    if shipped is None:
        raise Failure(1, "refused: nothing has shipped for order %s" % order.id)
    quote = price_order(shipped, data.catalog)
    if request.json:
        return to_json(quote_json(shipped, quote))
    return to_lines(quote_lines("invoice ", shipped, quote))


REPORT_FIELDS = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]


def cmd_report(request: Request, data: Data) -> str:
    rows = []
    for order in sorted(data.orders, key=lambda o: (o.date, order_number(o.id), o.id)):
        state = shipped_so_far(order, data.movements)
        shipped = shipped_order(order, data.movements)
        invoiced = price_order(shipped, data.catalog).total if shipped is not None else "0.00"
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": order_status(state),
                "ordered": sum(ordered for _s, ordered, _sh in state),
                "shipped": sum(sh for _s, _o, sh in state),
                "quoted": money(price_order(order, data.catalog).total),
                "invoiced": money(invoiced),
            }
        )
    if request.format == "json":
        return to_json(rows)
    if request.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(REPORT_FIELDS)
        for row in rows:
            writer.writerow([row[field] for field in REPORT_FIELDS])
        return buffer.getvalue()
    return to_lines(
        [
            "%s %s %s %s %d/%d %s %s"
            % (
                r["order"],
                r["date"],
                r["customer"],
                r["status"],
                r["shipped"],
                r["ordered"],
                r["quoted"],
                r["invoiced"],
            )
            for r in rows
        ]
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


def run(argv: Sequence[str]) -> str:
    """Carry out a command and return its standard output (raises Failure)."""
    request = parse_args(argv)
    texts = read_files(request.directory, COMMANDS[request.command][2])
    data = Data(texts)
    return HANDLERS[request.command](request, data)


def main(argv: Optional[Sequence[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        output = run(argv)
    except Failure as failure:
        sys.stderr.write("stockroom: %s\n" % failure.message)
        return failure.status
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
    return 0


def _silence_stdout() -> None:
    """After a broken pipe, point stdout at devnull so the final flush stays quiet."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass

