    parse_date,
    parse_movements,
    parse_orders,
    valid_order_id,
    valid_sku,
)
from .pricing import price_order
from .stock import buy_quantity, history, stock_levels, stock_status

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (allowed positional counts, allowed options, files read)
COMMANDS = {
    "stock": ((0,), ("--json",), (CATALOG, MOVEMENTS)),
    "low": ((0,), ("--json",), (CATALOG, MOVEMENTS)),
    "history": ((1,), ("--json",), (CATALOG, MOVEMENTS)),
    "receive": ((3, 4), (), (CATALOG, MOVEMENTS)),
    "ship": ((3, 4), (), (CATALOG, MOVEMENTS)),
    "quote": ((1,), ("--json",), (CATALOG, ORDERS)),
    "fulfil": ((2,), (), (CATALOG, MOVEMENTS, ORDERS)),
    "invoice": ((1,), ("--json",), (CATALOG, MOVEMENTS, ORDERS)),
    "report": ((0,), ("--format",), (CATALOG, MOVEMENTS, ORDERS)),
}
RAW_COMMANDS = ("receive", "ship", "fulfil")
FORMATS = ("text", "csv", "json")
QTY_RE = re.compile(r"[0-9]+")

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND ...\n"
    "commands: stock [--json], low [--json], history SKU [--json],\n"
    "          receive DATE SKU QUANTITY [NOTE], ship DATE SKU QUANTITY [NOTE],\n"
    "          quote ORDER [--json], fulfil ORDER DATE, invoice ORDER [--json],\n"
    "          report [--format text|csv|json]"
)


class Failure(Exception):
    """Stop with an exit status and a message for stderr."""

    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status = status
        self.message = message


def usage_error(message: str) -> Failure:
    return Failure(2, "%s\n%s" % (message, USAGE))


class Request:
    def __init__(self) -> None:
        self.directory = "."
        self.command = ""
        self.positionals: List[str] = []
        self.json = False
        self.format = "text"


def parse_args(argv: Sequence[str]) -> Request:
    request = Request()
    rest: List[str] = []
    tokens = list(argv)
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token == "--dir":
            if i + 1 >= len(tokens):
                raise usage_error("option --dir needs a value")
            request.directory = tokens[i + 1]
            i += 2
            continue
        if token.startswith("--dir="):
            request.directory = token[len("--dir="):]
            i += 1
            continue
        rest.append(token)
        i += 1
    if request.directory == "":
        raise usage_error("option --dir needs a value")

    command_index = None
    for index, token in enumerate(rest):
        if not _is_option(token):
            command_index = index
            break
    if command_index is None:
        if rest:
            raise usage_error("unknown option %s" % rest[0] if rest[0] not in ("--json", "--format") or True else "")
        raise usage_error("no command given")
    command = rest[command_index]
    if command not in COMMANDS:
        raise usage_error("unknown command %r" % command)
    request.command = command
    counts, options, _files = COMMANDS[command]
    others = rest[:command_index] + rest[command_index + 1:]

    if command in RAW_COMMANDS:
        request.positionals = others
    else:
        j = 0
        while j < len(others):
            token = others[j]
            if not _is_option(token):
                request.positionals.append(token)
            elif token == "--json" and "--json" in options:
                request.json = True
            elif token == "--format" and "--format" in options:
                if j + 1 >= len(others):
                    raise usage_error("option --format needs a value")
                request.format = _check_format(others[j + 1])
                j += 1
            elif token.startswith("--format=") and "--format" in options:
                request.format = _check_format(token[len("--format="):])
            else:
                raise usage_error("unknown option %s" % token)
            j += 1

    if len(request.positionals) not in counts:
        raise usage_error("wrong number of arguments for %s" % command)
    if command in ("receive", "ship", "fulfil"):
        date_text = request.positionals[0] if command != "fulfil" else request.positionals[1]
        if parse_date(date_text) is None:
            raise usage_error("bad date %r (expected YYYY-MM-DD)" % date_text)
    return request


def _is_option(token: str) -> bool:
    return len(token) > 1 and token.startswith("-")


def _check_format(value: str) -> str:
    if value not in FORMATS:
        raise usage_error("bad value for --format: %r (expected text, csv or json)" % value)
